  d=d-'presentation';
 end if;
 if d ? 'seo' then
  seo=d->'seo';
  if jsonb_typeof(seo) is distinct from 'object' or not seo ?& array['pages','image','image_alt'] or (seo-array['pages','image','image_alt'])<>'{}'::jsonb then return false;end if;
