-- Additive area content and snapshot filtering. No existing row updates or permission changes.
-- Optional content only. No row updates, grants, policies or publication changes.
begin;
create or replace function public.business_profile_valid(d jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare k text; h jsonb; l jsonb; hp jsonb; benefit jsonb; page_key text; page_doc jsonb; step jsonb; seo jsonb; section jsonb; card jsonb; area_key text; a jsonb; service jsonb; names text[];
begin
 if d ? 'area_pages' then
  if jsonb_typeof(d->'area_pages') is distinct from 'object' or (select count(*) from jsonb_object_keys(d->'area_pages'))>20 then return false;end if;
  names=array[]::text[];
  for area_key,a in select key,value from jsonb_each(d->'area_pages') loop
   if area_key !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(area_key) not between 2 and 64 or jsonb_typeof(a) is distinct from 'object' or not a ?& array['slug','name','title','introduction','coverage','seo_title','seo_description','action','published','services'] or (a-array['slug','name','title','introduction','coverage','seo_title','seo_description','action','published','services'])<>'{}'::jsonb then return false;end if;
   foreach k in array array['slug','name','title','introduction','coverage','seo_title','seo_description','action'] loop
    if jsonb_typeof(a->k) is distinct from 'string' or a->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
   end loop;
   if a->>'slug'<>area_key or char_length(btrim(a->>'name')) not between 1 and 120 or a->>'name'=any(names) or char_length(a->>'title')>120 or char_length(a->>'introduction')>600 or char_length(a->>'coverage')>3000 or char_length(a->>'seo_title')>120 or char_length(a->>'seo_description')>300 or char_length(a->>'action')>80 or jsonb_typeof(a->'published') is distinct from 'boolean' or jsonb_typeof(a->'services') is distinct from 'array' or jsonb_array_length(a->'services')>50 then return false;end if;
   names=array_append(names,a->>'name');
   if a->'published'='true'::jsonb and (btrim(a->>'title')='' or btrim(a->>'introduction')='' or btrim(a->>'coverage')='' or btrim(a->>'action')='') then return false;end if;
   for service in select value from jsonb_array_elements(a->'services') loop
    if jsonb_typeof(service) is distinct from 'string' or service#>>'{}' !~ '^[a-f0-9]{32}$' then return false;end if;
   end loop;
   if (select count(distinct value) from jsonb_array_elements(a->'services'))<>jsonb_array_length(a->'services') then return false;end if;
  end loop;
  d=d-'area_pages';
 end if;
 if d ? 'presentation' then
  seo=d->'presentation';
  if jsonb_typeof(seo) is distinct from 'object' or not seo ?& array['accent','font','whatsapp','street','city','region','postal','country'] or (seo-array['accent','font','whatsapp','street','city','region','postal','country','logo_size','show_name'])<>'{}'::jsonb then return false;end if;
  foreach k in array array['accent','font','whatsapp','street','city','region','postal','country'] loop
   if jsonb_typeof(seo->k) is distinct from 'string' or seo->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
  end loop;
  if seo->>'accent' not in ('','forest','navy','plum') or seo->>'font' not in ('','serif','sans') or (seo->>'whatsapp'<>'' and seo->>'whatsapp' !~ '^[1-9][0-9]{6,14}$') or (seo->>'country'<>'' and seo->>'country' !~ '^[A-Z]{2}$') or char_length(seo->>'street')>200 or char_length(seo->>'city')>100 or char_length(seo->>'region')>100 or char_length(seo->>'postal')>20 then return false;end if;
  if seo ? 'logo_size' and (jsonb_typeof(seo->'logo_size') is distinct from 'string' or seo->>'logo_size' not in ('32','48','64','80')) then return false;end if;
  if seo ? 'show_name' and (jsonb_typeof(seo->'show_name') is distinct from 'string' or seo->>'show_name' not in ('yes','no')) then return false;end if;
  d=d-'presentation';
 end if;
 if d ? 'seo' then
  seo=d->'seo';
  if jsonb_typeof(seo) is distinct from 'object' or not seo ?& array['pages','image','image_alt'] or (seo-array['pages','image','image_alt'])<>'{}'::jsonb then return false;end if;
  if jsonb_typeof(seo->'image_alt') is distinct from 'string' or char_length(seo->>'image_alt')>200 or seo->>'image_alt' ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
  if jsonb_typeof(seo->'pages') is distinct from 'object' or ((seo->'pages')-array['home','services','how-it-works','areas','contact'])<>'{}'::jsonb then return false;end if;
  for page_key,page_doc in select key,value from jsonb_each(seo->'pages') loop
   if jsonb_typeof(page_doc) is distinct from 'object' or not page_doc ?& array['title','description','image'] or (page_doc-array['title','description','image'])<>'{}'::jsonb then return false;end if;
   foreach k in array array['title','description','image'] loop
    if jsonb_typeof(page_doc->k) is distinct from 'string' or page_doc->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
   end loop;
   if char_length(page_doc->>'title')>120 or char_length(page_doc->>'description')>300 or page_doc->>'image' not in ('auto','hero','logo','none') then return false;end if;
  end loop;
  l=seo->'image';
  if l<>'null'::jsonb then
   if jsonb_typeof(l) is distinct from 'object' or (select count(*) from jsonb_object_keys(l))<>2 or not l ?& array['mime','data'] or jsonb_typeof(l->'mime') is distinct from 'string' or jsonb_typeof(l->'data') is distinct from 'string' or l->>'mime' not in ('image/png','image/jpeg','image/webp') or char_length(l->>'data')>200000 or l->>'data' !~ '^[A-Za-z0-9+/]+={0,2}$' or btrim(seo->>'image_alt')='' then return false;end if;
  end if;
  d=d-'seo';
 end if;
 if d ? 'pages' then
  if jsonb_typeof(d->'pages') is distinct from 'object' or ((d->'pages') - array['services','how-it-works','areas','contact'])<>'{}'::jsonb then return false;end if;
  for page_key,page_doc in select key,value from jsonb_each(d->'pages') loop
   if jsonb_typeof(page_doc) is distinct from 'object' or not page_doc ?& array['title','introduction','body'] or (page_doc - array['title','introduction','body','steps'])<>'{}'::jsonb then return false;end if;
   foreach k in array array['title','introduction','body'] loop
    if jsonb_typeof(page_doc->k) is distinct from 'string' or page_doc->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
   end loop;
   if char_length(page_doc->>'title')>120 or char_length(page_doc->>'introduction')>600 or char_length(page_doc->>'body')>3000 then return false;end if;
   if page_doc ? 'steps' then
    if page_key<>'how-it-works' or jsonb_typeof(page_doc->'steps') is distinct from 'array' or jsonb_array_length(page_doc->'steps')<>3 then return false;end if;
    for step in select value from jsonb_array_elements(page_doc->'steps') loop
     if jsonb_typeof(step) is distinct from 'array' or jsonb_array_length(step)<>2 or jsonb_typeof(step->0) is distinct from 'string' or jsonb_typeof(step->1) is distinct from 'string' or char_length(step->>0)>120 or char_length(step->>1)>600 or step->>0 ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' or step->>1 ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
    end loop;
   end if;
  end loop;
  d=d-'pages';
 end if;
 if d ? 'homepage' then
  hp=d->'homepage';
  if hp ? 'benefit_section' then
   section=hp->'benefit_section';
   if jsonb_typeof(section) is distinct from 'object' or (select count(*) from jsonb_object_keys(section))<>3 or not section ?& array['title','visible','cards'] or jsonb_typeof(section->'title') is distinct from 'string' or char_length(section->>'title')>120 or section->>'title' ~ '[[:cntrl:]]' or jsonb_typeof(section->'visible') is distinct from 'boolean' or jsonb_typeof(section->'cards') is distinct from 'array' or jsonb_array_length(section->'cards')>6 then return false;end if;
   for card in select value from jsonb_array_elements(section->'cards') loop
    if jsonb_typeof(card) is distinct from 'object' or (select count(*) from jsonb_object_keys(card))<>3 or not card ?& array['icon','title','description'] or jsonb_typeof(card->'icon') is distinct from 'string' or card->>'icon' not in ('home','calendar','message','check','heart','star') or jsonb_typeof(card->'title') is distinct from 'string' or char_length(btrim(card->>'title')) not between 1 and 200 or card->>'title' ~ '[[:cntrl:]]' or jsonb_typeof(card->'description') is distinct from 'string' or char_length(card->>'description')>200 or card->>'description' ~ '[[:cntrl:]]' then return false;end if;
   end loop;
   hp=hp-'benefit_section';
  end if;
  if jsonb_typeof(hp) is distinct from 'object' or (select count(*) from jsonb_object_keys(hp))<>5 or not hp ?& array['headline','introduction','image_alt','benefits','image'] then return false;end if;
  foreach k in array array['headline','introduction','image_alt'] loop
   if jsonb_typeof(hp->k) is distinct from 'string' or hp->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
  end loop;
  if char_length(hp->>'headline')>160 or char_length(hp->>'introduction')>600 or char_length(hp->>'image_alt')>200 then return false;end if;
  if jsonb_typeof(hp->'benefits') is distinct from 'array' or jsonb_array_length(hp->'benefits')>6 then return false;end if;
  for benefit in select value from jsonb_array_elements(hp->'benefits') loop
   if jsonb_typeof(benefit) is distinct from 'string' or char_length(benefit#>>'{}') not between 1 and 200 or benefit#>>'{}' ~ '[\u0001-\u001f\u007f]' then return false;end if;
  end loop;
  l=hp->'image';
  if l<>'null'::jsonb then
   if jsonb_typeof(l) is distinct from 'object' or (select count(*) from jsonb_object_keys(l))<>2 or not l ?& array['mime','data'] or jsonb_typeof(l->'mime') is distinct from 'string' or jsonb_typeof(l->'data') is distinct from 'string' or l->>'mime' not in ('image/png','image/jpeg','image/webp') or char_length(l->>'data')>200000 or l->>'data' !~ '^[A-Za-z0-9+/]+={0,2}$' or btrim(hp->>'image_alt')='' then return false;end if;
  end if;
  d=d-'homepage';
 end if;
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d))<>8 or not d ?& array['name','description','email','phone','website','areas','hours','logo'] then return false; end if;
 foreach k in array array['name','description','email','phone','website','areas'] loop
  if jsonb_typeof(d->k) is distinct from 'string' or d->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false; end if;
 end loop;
 if char_length(d->>'name') not between 2 and 120 or char_length(d->>'description')>2000 or char_length(d->>'email')>254 or char_length(d->>'phone')>40 or char_length(d->>'website')>500 or char_length(d->>'areas')>1000 then return false;end if;
 if (d->>'email'<>'' and d->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or (d->>'phone'<>'' and d->>'phone' !~ '^[+0-9 ()-]{5,40}$') or (d->>'website'<>'' and d->>'website' !~ '^https://[^/@[:space:]]+([/:?#][^[:space:]]*)?$') then return false; end if;
 if jsonb_typeof(d->'hours') is distinct from 'array' or jsonb_array_length(d->'hours')<>7 then return false;end if;
 for h in select value from jsonb_array_elements(d->'hours') loop
  if h='null'::jsonb then continue;end if;
  if jsonb_typeof(h) is distinct from 'array' or jsonb_array_length(h)<>2 then return false;end if;
  if jsonb_typeof(h->0) is distinct from 'string' or jsonb_typeof(h->1) is distinct from 'string' or h->>0 !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or h->>1 !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or h->>0>=h->>1 then return false;end if;
 end loop;
 l=d->'logo';if l<>'null'::jsonb then
  if jsonb_typeof(l) is distinct from 'object' or (select count(*) from jsonb_object_keys(l))<>2 or not l ?& array['mime','data'] or jsonb_typeof(l->'mime') is distinct from 'string' or jsonb_typeof(l->'data') is distinct from 'string' or l->>'mime' not in ('image/png','image/jpeg','image/webp') or char_length(l->>'data')>200000 or l->>'data' !~ '^[A-Za-z0-9+/]+={0,2}$' then return false;end if;
 end if;
 return true;
exception when others then return false;
end $$;

create or replace function public.business_profile_publish(p_business uuid,p_environment text,p_version integer) returns jsonb language plpgsql security invoker set search_path='' as $$
declare r public.business_profiles; zone text; snapshot jsonb;
begin
 select * into r from public.business_profiles where business_id=p_business and environment=p_environment for update;
 if not found or r.version<>p_version then raise exception 'Draft changed. Reload before saving or publishing.';end if;
 if btrim(r.draft->>'description')='' or btrim(r.draft->>'areas')='' or ((r.draft->>'email')='' and (r.draft->>'phone')='' and (r.draft->>'website')='') then raise exception 'Add a description, service areas and at least one public contact before publishing.';end if;
 select time_zone into zone from public.businesses where id=p_business;
 if zone is null then raise exception 'Complete business country and time zone first.';end if;
 snapshot=r.draft;
 if snapshot ? 'area_pages' then snapshot=jsonb_set(snapshot,'{area_pages}',coalesce((select jsonb_object_agg(key,value) from jsonb_each(snapshot->'area_pages') where value->'published'='true'::jsonb),'{}'::jsonb));end if;
 insert into public.business_public_pages(business_id,environment,slug,document,time_zone) values(p_business,p_environment,r.slug,snapshot,zone)
 on conflict(business_id,environment) do update set slug=excluded.slug,document=excluded.document,time_zone=excluded.time_zone;
 update public.business_profiles set published_at=now(),published_slug=r.slug where business_id=p_business and environment=p_environment;
 return '{}'::jsonb;
end $$;

commit;

begin;
-- Default-off dispatcher: no historical backfill or existing record changes.
create table enquiry_private.mail_settings(environment text primary key check(environment in ('preview','live')),enabled boolean not null default false);
insert into enquiry_private.mail_settings values('preview',false),('live',false);
create table enquiry_private.mail_outbox(
 id uuid primary key default gen_random_uuid(), enquiry_id uuid not null references public.business_enquiries(id) on delete restrict,
 business_id uuid not null references public.businesses(id) on delete restrict,environment text not null check(environment in ('preview','live')),
 kind text not null check(kind in ('admin','customer')),recipient text not null,reply_to text not null default '',payload jsonb not null,
 status text not null default 'pending' check(status in ('pending','sending','accepted','failed')),
 attempts integer not null default 0,available_at timestamptz not null default now(),lease uuid,leased_until timestamptz,
 first_attempt_at timestamptz,provider_id text,last_error text not null default '',created_at timestamptz not null default now(),
 unique(enquiry_id,kind)
);
alter table enquiry_private.mail_settings enable row level security;
alter table enquiry_private.mail_outbox enable row level security;
revoke all on enquiry_private.mail_settings,enquiry_private.mail_outbox from public,anon,authenticated;
create index enquiry_mail_ready on enquiry_private.mail_outbox(environment,status,available_at);
create function enquiry_private.queue_mail() returns trigger language plpgsql security definer set search_path='' as $$
declare owner_email text; doc jsonb; data jsonb; reply text;
begin
 -- Internal/manual records do not send unsolicited confirmations. Future public submissions only.
 if new.page_slug='' or not exists(select 1 from enquiry_private.mail_settings where environment=new.environment and enabled) then return new;end if;
 select p.document into doc from public.business_public_pages p where p.business_id=new.business_id and p.environment=new.environment and p.slug=new.page_slug;
 if doc is null then return new;end if;
 select u.email into owner_email from public.businesses b join auth.users u on u.id=b.owner_id where b.id=new.business_id and u.email_confirmed_at is not null;
 data=jsonb_build_object('business',doc->>'name','slug',new.page_slug,'customer',new.customer_name,'service',coalesce(nullif(new.service_name,''),'General enquiry'),'requirements',new.requirements,'email',new.email,'phone',new.phone,'reference',upper(left(replace(new.id::text,'-',''),8)));
 -- Only the verified owner receives private customer details. Editable public email cannot redirect admin alerts.
 if owner_email is not null and owner_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' and owner_email !~ '[[:cntrl:]]' then
  insert into enquiry_private.mail_outbox(enquiry_id,business_id,environment,kind,recipient,reply_to,payload) values(new.id,new.business_id,new.environment,'admin',owner_email,new.email,data);
 end if;
 if new.email<>'' then
  reply=case when coalesce(doc->>'email','') ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' and doc->>'email' !~ '[[:cntrl:]]' then doc->>'email' else '' end;
  -- Do not echo arbitrary free-text messages to an unverified address (mail-bomb/reflection abuse).
  insert into enquiry_private.mail_outbox(enquiry_id,business_id,environment,kind,recipient,reply_to,payload) values(new.id,new.business_id,new.environment,'customer',new.email,reply,data-array['customer','requirements','email','phone']);
 end if;
 return new;
end $$;
revoke all on function enquiry_private.queue_mail() from public,anon,authenticated;
create trigger enquiry_queue_mail after insert on public.business_enquiries for each row execute function enquiry_private.queue_mail();
create function public.business_enquiry_mail_claim(p_environment text) returns jsonb language plpgsql security definer set search_path='' as $$
declare job enquiry_private.mail_outbox;
begin
 if not exists(select 1 from enquiry_private.mail_settings where environment=p_environment and enabled) then return '{}'::jsonb;end if;
 -- Never retry outside provider idempotency retention; unknown sends require review.
 update enquiry_private.mail_outbox set status='failed',last_error='Retry window expired' where environment=p_environment and status in ('pending','sending') and ((first_attempt_at is not null and first_attempt_at<now()-interval '20 hours') or created_at<now()-interval '24 hours' or (attempts>=5 and leased_until<now()));
 select * into job from enquiry_private.mail_outbox where environment=p_environment and attempts<5 and ((status='pending' and available_at<=now()) or (status='sending' and leased_until<now())) order by created_at,id for update skip locked limit 1;
 if not found then return '{}'::jsonb;end if;
 update enquiry_private.mail_outbox set status='sending',attempts=attempts+1,first_attempt_at=coalesce(first_attempt_at,now()),lease=gen_random_uuid(),leased_until=now()+interval '2 minutes' where id=job.id returning * into job;
 return jsonb_build_object('id',job.id,'enquiry_id',job.enquiry_id,'kind',job.kind,'recipient',job.recipient,'reply_to',job.reply_to,'payload',job.payload,'lease',job.lease,'environment',job.environment);
end $$;
create function public.business_enquiry_mail_finish(p_id uuid,p_lease uuid,p_provider_id text,p_retry boolean,p_error text) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if char_length(coalesce(p_provider_id,''))>200 or p_error not in ('','Temporary provider failure','Provider rejected message','Recipient blocked in preview','Invalid mail configuration') then raise exception 'Invalid mail outcome';end if;
 update enquiry_private.mail_outbox set status=case when coalesce(p_provider_id,'')<>'' then 'accepted' when p_retry and attempts<5 then 'pending' else 'failed' end,provider_id=nullif(p_provider_id,''),last_error=p_error,available_at=now()+make_interval(secs=>least(3600,60*(2^attempts)::integer)),lease=null,leased_until=null where id=p_id and lease=p_lease and status='sending';
 if not found then raise exception 'Mail lease changed';end if;
 return '{}'::jsonb;
end $$;
revoke all on function public.business_enquiry_mail_claim(text),public.business_enquiry_mail_finish(uuid,uuid,text,boolean,text) from public,anon,authenticated;
grant execute on function public.business_enquiry_mail_claim(text),public.business_enquiry_mail_finish(uuid,uuid,text,boolean,text) to service_role;
-- Only the owner can inspect outcomes; recipients, bodies and credentials are not returned.
create function public.business_enquiry_mail_status(p_business uuid,p_environment text,p_enquiry uuid) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.businesses where id=p_business and owner_id=auth.uid()) or coalesce((auth.jwt()->>'is_anonymous')::boolean,true) then raise exception 'Enquiry unavailable';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'status',status,'attempts',attempts,'error',last_error)) from enquiry_private.mail_outbox where business_id=p_business and environment=p_environment and enquiry_id=p_enquiry),'[]'::jsonb);
end $$;
revoke all on function public.business_enquiry_mail_status(uuid,text,uuid) from public,anon;
grant execute on function public.business_enquiry_mail_status(uuid,text,uuid) to authenticated;
notify pgrst,'reload schema';
commit;

begin;
-- Additive private owner workspace; retain all existing enquiries and agreements.
alter table public.business_enquiries
 add column private_notes text not null default '' check(char_length(private_notes)<=2000 and private_notes !~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]'),
 add column follow_up_on date check(follow_up_on between date '2000-01-01' and date '2099-12-31');
grant update(private_notes,follow_up_on) on public.business_enquiries to authenticated;
create index enquiry_followups on public.business_enquiries(business_id,environment,follow_up_on) where status<>'Closed' and follow_up_on is not null;
create table public.business_enquiry_activity(
 id uuid primary key default gen_random_uuid(), enquiry_id uuid not null references public.business_enquiries(id) on delete restrict,
 created_at timestamptz not null default now(), actor_id uuid, event text not null,
 status text not null, private_notes text not null, follow_up_on date
);
alter table public.business_enquiry_activity enable row level security;
revoke all on public.business_enquiry_activity from public,anon,authenticated;
grant select on public.business_enquiry_activity to authenticated;
create policy enquiry_activity_read on public.business_enquiry_activity for select to authenticated
 using(exists(select 1 from public.business_enquiries e join public.businesses b on b.id=e.business_id where e.id=enquiry_id and b.owner_id=(select auth.uid()) and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true)));
create index enquiry_activity_history on public.business_enquiry_activity(enquiry_id,created_at desc,id desc);
-- The trigger alone appends activity. No caller can forge, change or delete it.
create function enquiry_private.record_activity() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if TG_OP='UPDATE' then
  if (new.status,new.private_notes,new.follow_up_on) is not distinct from (old.status,old.private_notes,old.follow_up_on) then return new;end if;
 end if;
 insert into public.business_enquiry_activity(enquiry_id,actor_id,event,status,private_notes,follow_up_on)
 values(new.id,auth.uid(),case when TG_OP='INSERT' then 'Created' else 'Updated' end,new.status,new.private_notes,new.follow_up_on);
 return new;
end$$;
revoke all on function enquiry_private.record_activity() from public,anon,authenticated;
create trigger enquiry_activity after insert or update on public.business_enquiries for each row execute function enquiry_private.record_activity();
create function public.business_enquiry_workflow_save(p_business uuid,p_environment text,p_id uuid,p_version integer,p_status text,p_notes text,p_follow_up date default null) returns jsonb
 language plpgsql security invoker set search_path='' as $$
begin
 if not exists(select 1 from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true)) then raise exception 'Enquiry unavailable';end if;
 if p_status is null or p_status not in ('New','Contacted','Closed') or p_notes is null or char_length(p_notes)>2000 then raise exception 'Check enquiry details';end if;
 update public.business_enquiries set status=p_status,private_notes=p_notes,follow_up_on=p_follow_up
 where id=p_id and business_id=p_business and environment=p_environment and version=p_version;
 if not found then raise exception 'Enquiry changed or unavailable. Reload before updating.';end if;
 return '{}'::jsonb;
end$$;
revoke all on function public.business_enquiry_workflow_save(uuid,text,uuid,integer,text,text,date) from public,anon;
grant execute on function public.business_enquiry_workflow_save(uuid,text,uuid,integer,text,text,date) to authenticated;
create function public.business_enquiry_workspace(p_business uuid,p_environment text,p_id uuid,p_activity_page integer default 1) returns jsonb
 language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if p_activity_page is null or p_activity_page not between 1 and 100000 then raise exception 'Choose a valid activity page';end if;
 if not exists(select 1 from public.business_enquiries e join public.businesses b on b.id=e.business_id where e.id=p_id and e.business_id=p_business and e.environment=p_environment and b.owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true)) then raise exception 'Enquiry unavailable';end if;
 select jsonb_build_object(
 'quotes',coalesce((select jsonb_agg(to_jsonb(t) order by created_at desc,id desc) from (
 select q.id,q.created_at,q.effective_status as status,q.document->>'currency' as currency,
 (select sum((i->>'quantity')::bigint*(i->>'price')::bigint) from jsonb_array_elements(q.document->'items') i) as total,
 (select b.id from public.business_bookings b where b.quote_id=q.id and b.business_id=p_business and b.environment=p_environment) as booking_id
 from public.business_quote_list q where q.enquiry_id=p_id and q.business_id=p_business and q.environment=p_environment order by q.created_at desc,q.id desc limit 21) t),'[]'::jsonb),
 'activity',coalesce((select jsonb_agg(to_jsonb(t) order by created_at desc,id desc) from (
 select id,created_at,event,status,private_notes,follow_up_on from public.business_enquiry_activity where enquiry_id=p_id order by created_at desc,id desc limit 21 offset (p_activity_page-1)*20) t),'[]'::jsonb)
 ) into result;return result;
end$$;
